using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using XHLLauncher;
class DesktopChecks {
 static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);count++;}
 static void Main(string[] args){try{Run(args);}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
 static void Run(string[] args){string root=Path.Combine(args[0],"desktop-fixture-"+Guid.NewGuid().ToString("N")),server=Path.Combine(root,"server"),app=Path.Combine(root,"app");Directory.CreateDirectory(Path.Combine(server,"savegame"));Directory.CreateDirectory(Path.Combine(server,"logs"));Directory.CreateDirectory(app);string cfg="{\"name\":\"Fixture\",\"saveDirectory\":\"savegame\",\"logDirectory\":\"logs\",\"slotCount\":16,\"queryPort\":15637,\"gameSettingsPreset\":\"Custom\",\"gameSettings\":{\"enemyDamageFactor\":0.6},\"userGroups\":[{\"name\":\"Admin\",\"password\":\"secret fixture password\",\"canKickBan\":true}]}";File.WriteAllText(Path.Combine(server,"enshrouded_server.json"),cfg);File.WriteAllText(Path.Combine(server,"savegame","world.ksd"),"world sentinel");File.WriteAllText(Path.Combine(server,"XHL-PLAYER-SESSIONS.csv"),"Player,Joined,Left,Duration\nFixture Visitor,2026-10-18 10:00:00,2026-10-18 10:10:00,600\n");string hash=InstallationAudit.Hash(Path.Combine(server,"savegame","world.ksd"));
  Check(DesktopWindow.TrustedSource("https://shroudforge.local/index.html"),"Local packaged interface can use the desktop bridge");foreach(string origin in new[]{"https://shroudforge.local.evil/index.html","https://enshroudeddatabase.com/map/","http://shroudforge.local/index.html","file:///index.html","https://shroudforge.local/other.html"})Check(!DesktopWindow.TrustedSource(origin),"Untrusted origin rejected: "+origin);
  var settings=new LauncherSettings{ServerRoot=server,ServerName="Fixture",PhoneViewEnabled=false,PublicIpLookup=false,PhoneViewKey="private-fixture-key",AutoBackup=false,AutoRestartOnCrash=false};using(var engine=new DesktopEngine(app,settings,true,()=>null)){engine.Start().GetAwaiter().GetResult();foreach(string op in new[]{"Start","Stop","Restart","SaveField","Restore","ModStartup","Recovery","AutoBackup","Backup","RemoveMod"}){var result=engine.Command(op,new Dictionary<string,object>()).GetAwaiter().GetResult();Check(!result.Success&&result.Message.StartsWith("Read-only preview"),"Preview denies "+op+" before any game or config action");}string json=new JavaScriptSerializer().Serialize(engine.Snapshot());Check(!json.Contains("secret fixture password")&&!json.Contains("private-fixture-key"),"Desktop state excludes group passwords and phone access keys");Check(json.Contains("Fixture Visitor")&&json.Contains("RECORDED VISITS"),"Completed-session identities and full observed profiles reach modern UI");Check(json.Contains("CURRENT SESSION   Unavailable")||json.Contains("CURRENT SESSION   Not available"),"Offline profiles do not invent a running session");Check(json.Contains("memoryHistory")&&json.Contains("cpuHistory"),"Both measured history series reach the dashboard");File.WriteAllText(Path.Combine(args[0],"snapshot.json"),json);Check(json.Contains("Join group not exposed")||json.Contains("individualRoles"),"Moderation capabilities are explicit rather than invented");}
  var probeSettings=new LauncherSettings{ServerRoot=server,PublicIpLookup=false};
  using(var telemetry=new TelemetryService(app,probeSettings,()=>null)){
   telemetry.ObserveProcess(()=>null);var stopped=telemetry.GetHost();Check(stopped.Observation==ProcessObservation.Stopped&&!stopped.ServerRunning,"Successful empty observation confirms stopped");
   telemetry.ObserveProcess(()=>{throw new UnauthorizedAccessException("fixture denied");});var failed=telemetry.GetHost();Check(failed.Observation==ProcessObservation.Failed&&failed.SampledUtc==stopped.SampledUtc&&failed.ObservationError.Contains("fixture denied"),"Discovery failure preserves last successful timestamp and exposes error");
   telemetry.ObserveProcess(()=>new System.Diagnostics.Process());Check(telemetry.GetHost().Observation==ProcessObservation.Failed,"Process property failure is not reported as a successful observation");
   telemetry.ObserveProcess(()=>null);Check(telemetry.GetHost().Observation==ProcessObservation.Stopped&&telemetry.GetHost().ObservationError=="","Successful observation clears failure");
  }
  var goodHost=new HostState{Observation=ProcessObservation.Running,ServerRunning=true,Pid=42,SampledUtc=DateTime.UtcNow.AddMinutes(-1)};var sampled=goodHost.SampledUtc;TelemetryService.MarkObservationFailed(goodHost,"fixture denied");Check(goodHost.ServerRunning&&goodHost.Pid==42&&goodHost.SampledUtc==sampled&&!goodHost.QueryResponsive,"Failed observation retains last known process without refreshing its age");
  var guard=new ResilienceGuard(Path.Combine(root,"observation-guard.json"));var now=DateTime.UtcNow;guard.Poll(true,ProcessObservation.Running,true,false,now);guard.Poll(true,ProcessObservation.Running,true,false,now.AddSeconds(31));
  Check(!guard.Poll(true,ProcessObservation.Failed,false,false,now.AddMinutes(2))&&!guard.State.Pending&&guard.State.Attempts.Count==0,"Observation failure never becomes an exit or recovery attempt");
  guard.Poll(true,ProcessObservation.Running,true,false,now.AddMinutes(3));guard.Poll(true,ProcessObservation.Stopped,false,false,now.AddMinutes(4));Check(guard.State.Pending,"Confirmed absence after running still schedules bounded recovery");
  Check(!guard.Poll(true,ProcessObservation.Failed,false,false,now.AddMinutes(6))&&guard.State.Attempts.Count==0,"Observation failure blocks even an already-due recovery");
  var goodScan=ScanSnapshot.Attempt(new ScanSnapshot(),()=>ScanSnapshot.Collect(app,settings,Path.Combine(app,"World-Backups")));Check(goodScan.Error==""&&goodScan.SuccessUtc!=DateTime.MinValue,"Fixture scan completes as one snapshot");
  File.WriteAllText(Path.Combine(server,"enshrouded_server.json"),"invalid JSON");var badScan=ScanSnapshot.Attempt(goodScan,()=>ScanSnapshot.Collect(app,settings,Path.Combine(app,"World-Backups")));
  Check(badScan.Error.Contains("Configuration scan failed")&&badScan.SuccessUtc==goodScan.SuccessUtc&&Object.ReferenceEquals(badScan.config,goodScan.config)&&Object.ReferenceEquals(badScan.files,goodScan.files),"Failed config scan retains complete last-good data and its age");
  Check(goodScan.Error=="","Failed scan does not mutate a snapshot already published");File.WriteAllText(Path.Combine(server,"enshrouded_server.json"),cfg);
  var recovered=ScanSnapshot.Attempt(badScan,()=>ScanSnapshot.Collect(app,settings,Path.Combine(app,"World-Backups")));Check(recovered.Error==""&&recovered.SuccessUtc>=goodScan.SuccessUtc,"Successful retry clears error and updates data age");
  string sessionPath=Path.Combine(server,"XHL-PLAYER-SESSIONS.csv");using(var held=new FileStream(sessionPath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){
   var failedHistory=ScanSnapshot.Attempt(recovered,()=>ScanSnapshot.Collect(app,settings,Path.Combine(app,"World-Backups")));Check(failedHistory.Error.Contains("Player history scan failed")&&failedHistory.SuccessUtc==recovered.SuccessUtc,"History read failures are visible rather than empty or silently retained");
  }
  var blockedBackup=Path.Combine(root,"not-a-backup-directory");File.WriteAllText(blockedBackup,"fixture");var backupScan=ScanSnapshot.Attempt(recovered,()=>ScanSnapshot.Collect(app,settings,blockedBackup));Check(backupScan.Error.Contains("Backup scan failed")&&Object.ReferenceEquals(backupScan.backups,recovered.backups),"Failed backup enumeration is not published as an empty successful list");
  bool observationRejected=false;try{new ServerControl("\0",settings).GetServerProcess();}catch(IOException){observationRejected=true;}Check(observationRejected,"Process discovery failure propagates instead of confirming absence");
  using(var reporting=new DesktopEngine(app,settings,true,()=>null)){reporting.Report(ActionResult.Fail("fixture failure"));Check(reporting.OperationFailed&&reporting.Operation=="fixture failure","Operation failure sets message and failure together");reporting.Report(ActionResult.Ok("fixture success"));Check(!reporting.OperationFailed&&reporting.Operation=="fixture success","Operation success clears an earlier failure");}
  Check(File.ReadAllText(Path.Combine(server,"enshrouded_server.json"))==cfg&&InstallationAudit.Hash(Path.Combine(server,"savegame","world.ksd"))==hash,"Preview leaves configuration and world bytes unchanged");
  string log=Path.Combine(root,"private.log");File.WriteAllText(log,"{\"password\":\"secret with spaces\"}\nPhoneViewKey=abcdef\nhttp://127.0.0.1:8765/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/status");string tail=IncidentEvidence.Tail(log,4096);Check(!tail.Contains("secret with spaces")&&!tail.Contains("abcdef")&&!tail.Contains("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),"Evidence redacts quoted credentials and private phone URL paths");Console.WriteLine(count+" desktop safety checks passed.");
 }
}
